import{_ as i,o as a,c as t,a3 as s,j as e,a as r}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/benutzer-einstellungen/verwaltung-email-versand-standard.png",d="/bilder/benutzer-einstellungen/verwaltung-email-versand-smtp.png",v=JSON.parse('{"title":"Den E-Mail-Versand einrichten","description":"","frontmatter":{"title":"Den E-Mail-Versand einrichten","source_pageid":920,"source_revision":6132},"headers":[],"relativePath":"administration/benutzer-einstellungen/e-mail-versand-verwaltung-globale-einstellungen.md","filePath":"administration/benutzer-einstellungen/e-mail-versand-verwaltung-globale-einstellungen.md"}'),o={name:"administration/benutzer-einstellungen/e-mail-versand-verwaltung-globale-einstellungen.md"};function u(g,n,h,m,c,p){return a(),t("div",null,[...n[0]||(n[0]=[s('<h1 id="den-e-mail-versand-einrichten" tabindex="-1">Den E-Mail-Versand einrichten <a class="header-anchor" href="#den-e-mail-versand-einrichten" aria-label="Permalink to &quot;Den E-Mail-Versand einrichten&quot;">​</a></h1><p>SchILD-NRW 3 kann E-Mails über das in Windows eingestellte E-Mail-Programm oder direkt über einen Mailserver versenden. Für den direkten Versand wird <strong>SMTP</strong> verwendet, das Übertragungsverfahren zum Versenden von E-Mails. Prüfen Sie außerdem die Empfängeradressierung und die Auswahl schulischer oder privater E-Mail-Adressen.</p><p>Es besteht an mehreren Stellen in SchILD die Option, direkt E-Mails zu versenden. Ein Beispiel wäre der Versand von erzeugten Reports per E-Mail, mitunter bietet aber auch die Oberfläche von SchILD an diversen Stellen einen E-Mail-Versand an.</p><p>Hierzu muss SchILD für E-Mails vorbereitet werden.</p><p><a href="/bilder/benutzer-einstellungen/verwaltung-email-versand-standard.png"><img src="'+l+'" alt="Einstellungen zum Email-Versand." loading="lazy"></a></p><p><em>Einstellungen zum Email-Versand.</em></p><p>Gehen Sie über <em>Verwaltung ➜ Einstellungen ➜ E-Mail-Versand</em>, um die notwendigen Konfigurationen vorzunehmen.</p><ul><li><strong>Simple MAPI verwenden</strong> schaltet eine vereinfachte Anbindung an das E-Mail-Programm ein. Einige E-Mail-Programme benötigen diese Einstellung. Prüfen Sie in der Dokumentation Ihres Programms und mit einer Testnachricht, welche Einstellung für Ihre Installation funktioniert.</li><li><strong>Bei Sammel-E-Mails Adressen als BCC eintragen</strong> sorgt dafür, dass unterschiedliche Empfänger die E-Mail-Adressen aller anderen Teilnehmer nicht sehen können. <strong>Es wird wegen modernem Datenschutz dringend empfohlen, diese Option zu aktivieren.</strong></li><li><strong>Verwendung von schulischen/dienstlichen E-Mail-Adressen von SuS/Lehrkräften</strong> legt fest, ob vorrangig die schulische beziehungsweise dienstliche oder die private Adresse verwendet wird. <strong>SuS</strong> steht hier für Schülerinnen und Schüler. Für die schulische Kommunikation werden schulische und dienstliche Adressen empfohlen.</li></ul><h2 id="aufruf-des-standard-e-mail-programmes" tabindex="-1">Aufruf des Standard-E-Mail-Programmes <a class="header-anchor" href="#aufruf-des-standard-e-mail-programmes" aria-label="Permalink to &quot;Aufruf des Standard-E-Mail-Programmes&quot;">​</a></h2><p>Typische Mailprogramme sind z.B. Outlook oder Thunderbird. Bei diesem Eintrag sendet SchILD-NRW die Mails über das Mailprogramm, welches in Windows als Standard für das Kommando &quot;mailto:&quot; definiert wurde.</p><p>Wählen Sie in den Windows-Einstellungen das vorgesehene Standardprogramm für E-Mail beziehungsweise <code>mailto:</code> aus. Prüfen Sie den Aufruf mit einer Testnachricht ohne personenbezogene Daten.</p><p>Außerdem sollten Sie im verwendeten Standardbrowser kontrollieren, ob das gewünschte Mailprogramm eingetragen ist.</p><h2 id="direkt-per-smtp" tabindex="-1">Direkt per SMTP <a class="header-anchor" href="#direkt-per-smtp" aria-label="Permalink to &quot;Direkt per SMTP&quot;">​</a></h2><p><a href="/bilder/benutzer-einstellungen/verwaltung-email-versand-smtp.png"><img src="'+d+'" alt="Konfiguration des SMPT-Servers." loading="lazy"></a></p><p><em>Konfiguration des SMPT-Servers.</em></p><p>Wenn Sie diese Einstellung wählen, müssen Sie in den folgenden Feldern Ihre SMTP-Server-Daten eintragen.</p><p>SchILD-NRW sendet dann direkt die Mails über diesen Server. Bitte entnehmen Sie die Einstellungen zu <strong>Server</strong>, <strong>Port</strong> und der jeweiligen <strong>SSL-Verschlüsselung</strong> den Informationen Ihres Mailproviders. Durch Deaktivierung der Option &quot;Konfiguration automatisch anpassen&quot; kann erreicht werden, dass die „SMTP-DLL“ keine eigenständigen Anpassungen bei den SMTP-Parametern macht.</p>',17),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),r("Hinweis")]),e("p",null,"Die Nachrichten werden nicht zwischengespeichert.")],-1),e("p",null,'Bei den individuellen Einstellungen wird dann die "SMTP-Schaltfläche" sichtbar und die Konto-Zugangsdaten des jeweiligen Users können eingetragen werden.',-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=E-Mail-Versand_(Verwaltung_Globale_Einstellungen)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),r(" · Quellrevision 6132.")],-1)])])}const S=i(o,[["render",u]]);export{v as __pageData,S as default};
